{"java":"package io.github.amxooo.voiceinput2pc;

/**
 * Pure layout/state policy for the compact IME UI. No Android dependencies.
 */
public final class CompactImeUiPolicy {

    public static final int MIC_TOUCH_DP = 48;
    public static final int MIC_DIAMETER_DP = 36;
    public static final int DOCK_BOTTOM_DP = 80;

    private static final int PORTRAIT_BASE_DP = 220;
    private static final int LANDSCAPE_BASE_DP = 188;
    private static final int COMPOSING_EXTRA_DP = 48;
    private static final int REMOTE_DRAFT_EXTRA_DP = 48;

    private static final int COLOR_LISTENING = 0xffc83a41;
    private static final int COLOR_RECOGNIZING = 0xffb9801e;
    private static final int COLOR_IDLE = 0xff60707e;

    private CompactImeUiPolicy() {
    }

    /**
     * Stateless: result depends only on arguments, so repeated calls never accumulate.
     */
    public static int keyboardHeightDp(boolean landscape, boolean composing, boolean remote) {
        int height = landscape ? LANDSCAPE_BASE_DP : PORTRAIT_BASE_DP;
        if (composing) {
            height += COMPOSING_EXTRA_DP;
        }
        if (remote) {
            height += REMOTE_DRAFT_EXTRA_DP;
        }
        return height;
    }

    public static int microphoneColor(InputSession.State state) {
        if (state == InputSession.State.LISTENING) {
            return COLOR_LISTENING;
        }
        if (state == InputSession.State.RECOGNIZING) {
            return COLOR_RECOGNIZING;
        }
        return COLOR_IDLE;
    }

    public static boolean canRunEditorAction(InputSession.State state, boolean remote, boolean remoteCanSend) {
        if (isVoiceBusy(state)) {
            return false;
        }
        return !remote || remoteCanSend;
    }

    private static boolean isVoiceBusy(InputSession.State state) {
        return state == InputSession.State.LISTENING || state == InputSession.State.RECOGNIZING;
    }
}
","test_java":"package io.github.amxooo.voiceinput2pc;

public final class CompactImeUiPolicyTest {

    private CompactImeUiPolicyTest() {
    }

    public static void main(String[] args) {
        testKeyboardHeights();
        testNoAccumulation();
        testMicrophoneColors();
        testBusyStatesBlockActions();
        testPreviewAllowsRetryActions();
        testIdleActions();
        testTouchTarget();
        System.out.println("CompactImeUiPolicyTest: all passed");
    }

    private static void testKeyboardHeights() {
        eq(220, CompactImeUiPolicy.keyboardHeightDp(false, false, false), "portrait base");
        eq(268, CompactImeUiPolicy.keyboardHeightDp(false, true, false), "portrait composing");
        eq(268, CompactImeUiPolicy.keyboardHeightDp(false, false, true), "portrait remote");
        eq(316, CompactImeUiPolicy.keyboardHeightDp(false, true, true), "portrait composing+remote");
        eq(188, CompactImeUiPolicy.keyboardHeightDp(true, false, false), "landscape base");
        eq(236, CompactImeUiPolicy.keyboardHeightDp(true, true, false), "landscape composing");
        eq(236, CompactImeUiPolicy.keyboardHeightDp(true, false, true), "landscape remote");
        eq(284, CompactImeUiPolicy.keyboardHeightDp(true, true, true), "landscape composing+remote");
    }

    private static void testNoAccumulation() {
        for (int i = 0; i < 5; i++) {
            eq(316, CompactImeUiPolicy.keyboardHeightDp(false, true, true), "repeat portrait full");
            eq(220, CompactImeUiPolicy.keyboardHeightDp(false, false, false), "repeat portrait base");
            eq(284, CompactImeUiPolicy.keyboardHeightDp(true, true, true), "repeat landscape full");
            eq(188, CompactImeUiPolicy.keyboardHeightDp(true, false, false), "repeat landscape base");
        }
    }

    private static void testMicrophoneColors() {
        eqHex(0xffc83a41, CompactImeUiPolicy.microphoneColor(InputSession.State.LISTENING), "listening color");
        eqHex(0xffb9801e, CompactImeUiPolicy.microphoneColor(InputSession.State.RECOGNIZING), "recognizing color");
        eqHex(0xff60707e, CompactImeUiPolicy.microphoneColor(InputSession.State.IDLE), "idle color");
        eqHex(0xff60707e, CompactImeUiPolicy.microphoneColor(InputSession.State.PREVIEW), "preview color");
    }

    private static void testBusyStatesBlockActions() {
        InputSession.State[] busy = {InputSession.State.LISTENING, InputSession.State.RECOGNIZING};
        boolean[] flags = {false, true};
        for (InputSession.State s : busy) {
            for (boolean remote : flags) {
                for (boolean canSend : flags) {
                    check(!CompactImeUiPolicy.canRunEditorAction(s, remote, canSend),
                            "busy " + s + " remote=" + remote + " canSend=" + canSend + " must be blocked");
                }
            }
        }
    }

    private static void testPreviewAllowsRetryActions() {
        InputSession.State p = InputSession.State.PREVIEW;
        check(CompactImeUiPolicy.canRunEditorAction(p, false, false), "preview local allowed");
        check(CompactImeUiPolicy.canRunEditorAction(p, false, true), "preview local allowed (flag ignored)");
        check(CompactImeUiPolicy.canRunEditorAction(p, true, true), "preview remote sendable allowed");
        check(!CompactImeUiPolicy.canRunEditorAction(p, true, false), "preview remote unsendable blocked");
    }

    private static void testIdleActions() {
        InputSession.State i = InputSession.State.IDLE;
        check(CompactImeUiPolicy.canRunEditorAction(i, false, false), "idle local allowed");
        check(CompactImeUiPolicy.canRunEditorAction(i, true, true), "idle remote sendable allowed");
        check(!CompactImeUiPolicy.canRunEditorAction(i, true, false), "idle remote unsendable blocked");
    }

    private static void testTouchTarget() {
        eq(48, CompactImeUiPolicy.MIC_TOUCH_DP, "touch dp");
        eq(36, CompactImeUiPolicy.MIC_DIAMETER_DP, "diameter dp");
        eq(80, CompactImeUiPolicy.DOCK_BOTTOM_DP, "dock bottom dp");
        check(CompactImeUiPolicy.MIC_TOUCH_DP >= 48, "touch target at least 48dp");
        check(CompactImeUiPolicy.MIC_TOUCH_DP >= CompactImeUiPolicy.MIC_DIAMETER_DP, "touch target >= icon");
    }

    private static void eq(int expected, int actual, String msg) {
        if (expected != actual) {
            throw new AssertionError(msg + ": expected " + expected + " but was " + actual);
        }
    }

    private static void eqHex(int expected, int actual, String msg) {
        if (expected != actual) {
            throw new AssertionError(msg + ": expected 0x" + Integer.toHexString(expected)
                    + " but was 0x" + Integer.toHexString(actual));
        }
    }

    private static void check(boolean cond, String msg) {
        if (!cond) {
            throw new AssertionError(msg);
        }
    }
}
","notes":"纯Java、无Android依赖、无I/O。keyboardHeightDp为无状态纯函数（基值+各标志各加一次48），因此不会重复累加；调用方应每次用当前状态重新计算并直接设置高度，而不是在旧高度上累加。microphoneColor与canRunEditorAction对null状态按非busy处理（灰蓝/按本机-远端规则），未引用除LISTENING/RECOGNIZING/IDLE/PREVIEW外的状态。测试不使用assert关键字，无需-ea；编译示例：javac -d out InputSession.java CompactImeUiPolicy.java CompactImeUiPolicyTest.java && java -cp out io.github.amxooo.voiceinput2pc.CompactImeUiPolicyTest（若InputSession依赖Android类，需提供只含State枚举的桩或在JVM单元测试源集中运行）。0xff...字面量在Java中为合法负int，可直接传给View#setBackgroundColor等ARGB接口。"}
